def metric_names(suite=None):
    """Registry names for one suite (the suite's own metrics, then X), or every metric (L, F, V, then X)."""
    xs = [n for n in METRICS if n.startswith("x_")]
    if suite is None:
        return [n for s in "LFV" for n in METRICS if METRICS[n]["suites"] == s] + xs
    if suite == "X":
        return xs
    if suite not in ("L", "F", "V"):
        return []
    return [n for n in METRICS if METRICS[n]["suites"] == suite] + xs


def headline(suite):
    """The suite's headline metric name (x_clean for X)."""
    for n in METRICS:
        if METRICS[n]["headline"] and (METRICS[n]["suites"] == suite or (suite == "X" and n.startswith("x_"))):
            return n
    return None


