def is_protected(rel):
    """swegemma.harness.verification._is_protected_test_or_config_path, copied (stdlib only)."""
    parts = rel.split("/")
    name = parts[-1]
    if name in {"conftest.py", "pytest.ini", "pyproject.toml", "tox.ini", "setup.cfg", ".pytest.ini", "sitecustomize.py",
                "usercustomize.py", "_swegemma_stubs.py"} or name.endswith(".pth"):
        return True
    if (name.startswith("test_") and name.endswith(".py")) or name.endswith("_test.py"):
        return True
    return bool({"tests", "test", "testing"} & {p.lower() for p in parts[:-1]} and name.endswith(".py"))


def patch_files(text):
    """[(path, is_new)] from a git diff (quoted paths unquoted)."""
    out, cur = [], None
    for line in text.splitlines():
        m = re.match(r'^diff --git "?a/(.*?)"? "?b/(.*?)"?$', line)
        if m:
            cur = [m.group(2), False]
            out.append(cur)
        elif cur is not None and line.startswith("new file mode"):
            cur[1] = True
    return [(p, n) for p, n in out]


def scratch_files(files):
    return [p for p, new in files if new and (SCRATCH_ROOT.search(p) and "/" not in p or SCRATCH_ANY.search(p)
                                               or VENDORED.search(p))]


def _call_name(msg):
    """The function name of a tool call the model wrote as text (<|tool_call>call:NAME...), or None."""
    m = TOOLCALL_TEXT.search(msg or "")
    return m.group(1).strip() if m else None


# ---------------------------------------------------------------------------------------------------------------------
# Trace parsing
# ---------------------------------------------------------------------------------------------------------------------
def _d(x):
    return x if isinstance(x, dict) else {}


def _l(x):
    return x if isinstance(x, list) else []


def _pick(d, *keys):
    for k in keys:
        if isinstance(d, dict) and d.get(k) is not None:
            return d[k]
    return None


def _num(x):
    """A finite int/float (bool excluded) or None."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        return None
    return x if math.isfinite(x) else None


def _int(x):
    v = _num(x)
    return int(v) if v is not None else None


def _flat(x):
    """Every string inside x (dict values in sorted key order) joined by newlines: what a result 'contains'."""
    if x is None:
        return ""
    if isinstance(x, str):
        return x
    if isinstance(x, (bool, int, float)):
        return json.dumps(x)
    if isinstance(x, dict):
        return "\n".join(_flat(x[k]) for k in sorted(x, key=str))
    if isinstance(x, (list, tuple)):
        return "\n".join(_flat(v) for v in x)
    return str(x)


def _resp_obj(resp):
    """A function_response payload; {"result": "<json object text>"} is unwrapped to that object."""
    if isinstance(resp, dict) and len(resp) == 1 and isinstance(resp.get("result"), str):
        s = resp["result"].strip()
        if s.startswith("{"):
            try:
                obj = json.loads(s)
            except ValueError:
                return resp
            if isinstance(obj, dict):
                return obj
    return resp


def _stdout(resp):
    """The helper's printed output: stdout, else result, else every string."""
    r = _d(resp)
    for k in ("stdout", "result"):
        if isinstance(r.get(k), str):
            return r[k]
    return _flat(resp)


def _events(agent_data):
    """Flat, ordered, normalised events: {i, author, texts, calls [{name, args}], resps [{name, response}]}.
    Events without content are skipped (agents-cli drops them before grading); thought parts are not text."""
    out = []
    for turn in _l(_d(agent_data).get("turns")):
        for ev in _l(_d(turn).get("events")):
            content = _d(ev).get("content")
            if not isinstance(content, dict):
                continue
            texts, calls, resps = [], [], []
            for p in _l(content.get("parts")):
                if not isinstance(p, dict):
                    continue
                fc = _pick(p, "function_call", "functionCall")
                fr = _pick(p, "function_response", "functionResponse")
                if isinstance(fc, dict):
                    nm, args = fc.get("name"), fc.get("args")
                    calls.append({"name": nm if isinstance(nm, str) else "", "args": args if isinstance(args, dict) else {}})
                elif isinstance(fr, dict):
                    nm = fr.get("name")
                    resps.append({"name": nm if isinstance(nm, str) else "", "response": _resp_obj(fr.get("response"))})
                elif isinstance(p.get("text"), str) and not p.get("thought"):
                    texts.append(p["text"])
            author = ev.get("author")
            out.append({"i": len(out), "author": author if isinstance(author, str) else "", "texts": texts,
                        "calls": calls, "resps": resps})
    # One model response with text AND calls is one ADK event, but an ATIF step keeps them apart and the trace writer
    # emits the text as its own event just before the calls. A text-only response ends an ADK agent's stage, so a
    # text event directly followed by the same author's call event can only be that split: join them, so the text is
    # not a "text reply" (replay_l4's kind "text" also needs a step without tool calls).
    for k in range(len(out) - 1):
        e, nxt = out[k], out[k + 1]
        if e["texts"] and not e["calls"] and not e["resps"] and nxt["calls"] and nxt["author"] == e["author"]:
            nxt["texts"] = e["texts"] + nxt["texts"]
            e["texts"] = []
    return out


def _is_text(e):
    """A text reply: text parts and no function call or response."""
    return bool(e["texts"]) and not e["calls"] and not e["resps"]


def _text(e):
    return "".join(e["texts"])


def _first_run(events, agent):
    """The agent's first stage-run: from its first event while the author stays the agent (or "tool")."""
    run, started = [], False
    for e in events:
        if e["author"] == agent:
            started = True
            run.append(e)
        elif started and e["author"] == "tool":
            run.append(e)
        elif started:
            break
    return run


def _uses(run):
    """Tool uses in call order, each paired with its response: the first pending call of the same name, else the
    first pending call. {name, args, cmd, resp, answered}."""
    uses, pending = [], []
    for e in run:
        for c in e["calls"]:
            cmd = c["args"].get("command")
            u = {"name": c["name"], "args": c["args"], "cmd": cmd if isinstance(cmd, str) else "", "resp": None,
                 "answered": False}
            uses.append(u)
            pending.append(u)
        for r in e["resps"]:
            match = None
            for u in pending:
                if u["name"] == r["name"]:
                    match = u
                    break
            if match is None and pending:
                match = pending[0]
            if match is not None:
                match["resp"], match["answered"] = r["response"], True
                pending.remove(match)
    return uses


def _suite_from_id(case_id):
    m = re.match(r"^([LFV])__", case_id if isinstance(case_id, str) else "")
    return m.group(1) if m else None


def _ctx(instance):
    """Everything the metrics read, parsed once."""
    inst = _d(instance)
    g = _d(inst.get("golden"))
    suite = g.get("suite") if isinstance(g.get("suite"), str) else _suite_from_id(inst.get("eval_case_id"))
    status = g.get("status") if isinstance(g.get("status"), str) else "ok"
    live = [a for a in _l(g.get("live_agents")) if isinstance(a, str) and a]
    stage_agent = SUITE_AGENT.get(suite)
    if not live and stage_agent:
        live = [stage_agent]
    events = _events(inst.get("agent_data"))
    runs = {}
    for a in live + ([stage_agent] if stage_agent else []):
        if a not in runs:
            runs[a] = _first_run(events, a)
    seen, live_events = set(), []
    for a in live:
        for e in runs[a]:
            if e["i"] not in seen:
                seen.add(e["i"])
                live_events.append(e)
    live_events.sort(key=lambda e: e["i"])
    ec = g.get("exec_checks")
    return {"inst": inst, "g": g, "suite": suite, "status": status, "live": live, "stage_agent": stage_agent,
            "events": events, "runs": runs, "live_events": live_events,
            "calls": [r for r in _l(g.get("llm_calls")) if isinstance(r, dict)],
            "has_calls": isinstance(g.get("llm_calls"), list), "ec": ec if isinstance(ec, dict) else None}


# ---------------------------------------------------------------------------------------------------------------------
# Results
# ---------------------------------------------------------------------------------------------------------------------
def _res(score, applicable=True, detail=None):
    s = _num(score)
    return {"score": float(s) if s is not None else 0.0,
            "explanation": json.dumps({"applicable": bool(applicable), "detail": detail}, sort_keys=True, default=str)}


def _na(why):
    return _res(0.0, False, why)


def explain(result):
    """(applicable, detail) of a metric result; an unreadable explanation counts as inapplicable."""
    try:
        e = json.loads(_d(result).get("explanation") or "")
    except ValueError:
        return False, {"error": "unreadable explanation"}
    e = _d(e)
    return bool(e.get("applicable")), e.get("detail")


def _gate(c, name):
    """None when the metric applies to this case, else the reason it does not."""
    suites = METRICS[name]["suites"]
    if not c["g"]:
        return "no golden block"
    if c["suite"] not in ("L", "F", "V") or c["suite"] not in suites:
        return "suite %s" % c["suite"]
    if c["status"] not in COUNTED_STATUS:
        return "status %s" % c["status"]
    if suites in ("F", "V") and c["g"].get("gradable") is not True:
        return "not gradable"
    return None


def _metric(name, instance, c, body):
    if c is None:
        c = _ctx(instance)
    why = _gate(c, name)
    if why is not None:
        return _na(why)
    return body(c)


def _score(name, instance):
    """The generated metric files' entry point. Never raises: a crash becomes applicable false with the error, which
    summary.py reports as a metric error (an exception would make agents-cli drop the case silently from its mean)."""
    try:
        fn = globals().get("m_" + name) if name in METRICS else None
        if fn is None:
            return _na({"error": "unknown metric %s" % name})
        return fn(instance)
    except Exception as e:  # noqa: BLE001
        return _na({"error": "%s: %s" % (type(e).__name__, str(e)[:300])})


def score_all(instance, names=None):
    """{name: result} for `names` (default: the metrics of the case's suite), parsing the trace once. Equal to
    calling _score(name, instance) for each name."""
    try:
        c = _ctx(instance)
    except Exception as e:  # noqa: BLE001
        c, err = None, _na({"error": "%s: %s" % (type(e).__name__, str(e)[:300])})
    if names is None:
        names = metric_names(c["suite"]) if c is not None and c["suite"] in ("L", "F", "V") else metric_names()
    out = {}
    for n in names:
        if c is None:
            out[n] = err
            continue
        fn = globals().get("m_" + n) if n in METRICS else None
        if fn is None:
            out[n] = _na({"error": "unknown metric %s" % n})
            continue
        try:
            out[n] = fn(instance, c)
        except Exception as e:  # noqa: BLE001
            out[n] = _na({"error": "%s: %s" % (type(e).__name__, str(e)[:300])})
    return out


def make_instance(case):
    """The instance agents-cli 1.7.0 builds from a grading-input trace case: every case field except responses and
    prompt, plus response = responses[0].response."""
    case = _d(case)
    inst = dict((k, v) for k, v in case.items() if k not in ("responses", "prompt"))
    resp = _l(case.get("responses"))
    inst["response"] = _d(resp[0]).get("response") if resp else None
    return inst


# ---------------------------------------------------------------------------------------------------------------------
# Shared computations
# ---------------------------------------------------------------------------------------------------------------------
def _snip(s, n=80):
    s = s if isinstance(s, str) else json.dumps(s, default=str)
    return s if len(s) <= n else s[:n] + "..."


def _x_counts(events):
    """The X counters over a list of normalised events (replay_l4 rules where they exist)."""
    out = dict((k, 0) for k in ("parsed_invented", "unparsed_invented", "unparsed_real", "helper_parsed",
                                "helper_unparsed", "helper_shell", "malformed", "forbidden_edit", "edit_fail",
                                "text_calls", "cant_open"))
    ex = {}

    def note(key, item):
        lst = ex.setdefault(key, [])
        if len(lst) < 5:
            lst.append(item)

    for e in events:
        for call in e["calls"]:
            nm = call["name"]
            if nm and nm not in TOOLS:
                out["parsed_invented"] += 1
                note("parsed_invented", "%d:%s" % (e["i"], _snip(nm, 40)))
                if HELPER_LIKE.match(nm.strip()):
                    out["helper_parsed"] += 1
            if nm in ("edit_file", "write_file"):
                out["forbidden_edit"] += 1
            cmd = call["args"].get("command")
            if nm == "run_command" and cmd:
                first = str(cmd).strip().split("\n")[0]
                if HELPER_SHELL.match(first):
                    out["helper_shell"] += 1
                    note("helper_shell", "%d:%s" % (e["i"], _snip(first, 60)))
        for r in e["resps"]:
            if MALFORMED in _flat(r["response"]):
                out["malformed"] += 1
                note("malformed", "%d:%s" % (e["i"], r["name"]))
        if _is_text(e) and TEXT_CALL in _text(e):
            out["text_calls"] += 1
            name = _call_name(_text(e)) or ""
            base = name.split(" ")[0].split("(")[0]
            if base in TOOLS:
                out["unparsed_real"] += 1
            else:
                out["unparsed_invented"] += 1
                note("unparsed_invented", "%d:%s" % (e["i"], _snip(name, 40)))
                if HELPER_LIKE.match(base):
                    out["helper_unparsed"] += 1
    runs, cur = [], None
    for e in events:   # pair calls with results inside each author's consecutive run
        if cur is None or (e["author"] != cur[0] and e["author"] != "tool"):
            cur = [e["author"], []]
            runs.append(cur)
        cur[1].append(e)
    for _, run in runs:
        for u in _uses(run):
            if u["name"] != "run_command":
                continue
            res = _flat(u["resp"])
            if "/tmp/swe/" in json.dumps(u["args"], sort_keys=True, default=str) and CANT_OPEN in res:
                out["cant_open"] += 1
                note("cant_open", _snip(u["cmd"], 60))
            if EDIT_CMD.search(u["cmd"]) and EDIT_FAIL.search(res):
                out["edit_fail"] += 1
                note("edit_fail", EDIT_FAIL.search(res).group(1))
    out["examples"] = ex
    return out


def _x(c):
    if "_x" not in c:
        c["_x"] = _x_counts(c["live_events"])
    return c["_x"]


def _live_calls(c, agent=None):
    return [r for r in c["calls"] if r.get("live") and r.get("served") in LIVE_SERVED
            and (agent is None or r.get("agent") in (agent, None))]


def _ordered(calls):
    return [r for _, r in sorted(enumerate(calls), key=lambda p: (
        _num(p[1].get("i")) if _num(p[1].get("i")) is not None else float(p[0]),
        _num(p[1].get("t_in")) or 0.0, p[0]))]


def _is_summ(r):
    return r.get("kind") == "summarizer" or r.get("agent") == "_summarizer"


def _compactions(c):
    """Summariser calls attributed to the live first stage-run. ADK compacts in a request processor BEFORE the call
    that triggers it (flows/llm_flows/compaction.py), so each summariser record belongs to the next non-summariser
    request (the previous one when it is the last record)."""
    recs = _ordered(c["calls"])
    live = set(c["live"])
    flags, started, ended = [], False, False
    for r in recs:
        if _is_summ(r):
            flags.append(None)
        elif not ended and r.get("agent") in live:
            started = True
            flags.append(True)
        else:
            ended = ended or started
            flags.append(False)
    n = 0
    for k, f in enumerate(flags):
        if f is not None:
            continue
        nxt = [x for x in flags[k + 1:] if x is not None]
        prv = [x for x in flags[:k] if x is not None]
        owner = nxt[0] if nxt else (prv[-1] if prv else False)
        n += bool(owner)
    return n


def _stage(c):
    return c["runs"].get(c["stage_agent"]) or []


def _reply(c):
    """The stage's final reply: its last text reply; the case response only when the stage has no events at all."""
    run = _stage(c)
    for e in reversed(run):
        if _is_text(e):
            return _text(e)
    if run:
        return ""
    resp = _d(c["inst"].get("response"))
    return "".join(p["text"] for p in _l(resp.get("parts"))
                   if isinstance(p, dict) and isinstance(p.get("text"), str) and not p.get("thought"))


def _footers(run):
    ts = []
    for e in run:
        for r in e["resps"]:
            ts.extend(int(x) for x in FOOT_T.findall(_flat(r["response"])))
    return ts


def _ec(c, key):
    """exec_checks[key] when it is a bool, else None (not computed)."""
    v = (c["ec"] or {}).get(key)
    return v if isinstance(v, bool) else None


def _patch_list(c):
    """[(path, is_new)] from exec_checks.patch_files, else parsed from golden.final_patch; None when neither."""
    pf = (c["ec"] or {}).get("patch_files")
    if isinstance(pf, list):
        out = []
        for x in pf:
            if isinstance(x, (list, tuple)) and x and isinstance(x[0], str):
                out.append((x[0], bool(x[1]) if len(x) > 1 else False))
        return out
    fp = c["g"].get("final_patch")
    return patch_files(fp) if isinstance(fp, str) else None


def _nonempty(files):
    src = [p for p, n in files if p.endswith((".py", ".pyi")) and not is_protected(p) and not scratch_files([(p, n)])]
    return bool(src), src


def _path_named(text, path):
    p = path[2:] if path.startswith("./") else path
    rx = r"(?:^|(?<=[^\w./-]))(?:\./|/workspace/)?" + re.escape(p) + r"(?![\w/])"
    return re.search(rx, text) is not None


def _gold_files(c):
    return [f for f in _l(c["g"].get("gold_files")) if isinstance(f, str) and f]


# ---------------------------------------------------------------------------------------------------------------------
# Bodies shared by several suites
# ---------------------------------------------------------------------------------------------------------------------
def _b_ended(c):
    run = [e for e in _stage(c) if e["author"] == c["stage_agent"]]
    if not run:
        return _res(0, True, "no events in the stage-run")
    last = run[-1]
    ok = _is_text(last) and TEXT_CALL not in _text(last)
    return _res(1 if ok else 0, True, {"last": "text" if _is_text(last) else "tool",
                                       "text_call": _is_text(last) and TEXT_CALL in _text(last)})


def _b_t_end(c):
    ts = _footers(_stage(c))
    return _res(ts[-1], True, {"footers": len(ts)}) if ts else _na("no helper footer in the stage-run")


def _b_within_time(limit):
    def body(c):
        ts = _footers(_stage(c))
        if not ts:
            return _na("no helper footer in the stage-run")
        return _res(1 if ts[-1] <= limit else 0, True, {"t_end": ts[-1], "limit": limit})
    return body


def _b_calls(c):
    return _res(sum(len(e["calls"]) for e in _stage(c)), True, None)


def _b_llm_calls(c):
    if not c["has_calls"]:
        return _na("no llm_calls in the golden block")
    return _res(len(_live_calls(c, c["stage_agent"])), True, None)


def _b_prompt_tokens(c):
    if not c["has_calls"]:
        return _na("no llm_calls in the golden block")
    calls = _live_calls(c, c["stage_agent"])
    return _res(sum(_int(r.get("prompt_tokens")) or 0 for r in calls), True, {"calls": len(calls)})


def _b_hidden_pass(c):
    if c["status"] == "model_error":
        return _res(0, True, "model_error counts as a failure")
    v = _ec(c, "hidden_pass")
    if v is None:
        return _na("exec_checks.hidden_pass not computed")
    ec = c["ec"] or {}
    return _res(1 if v else 0, True, {"hidden_why": _snip(ec.get("hidden_why") or "", 160),
                                      "retried": ec.get("hidden_retried")})


def _b_exec_bool(key):
    def body(c):
        v = _ec(c, key)
        if v is None:
            return _na("exec_checks.%s not computed" % key)
        return _res(1 if v else 0, True, None)
    return body


def _b_no_protected(c):
    files = _patch_list(c)
    if files is None:
        return _na("no patch_files and no final_patch")
    bad = [p for p, _ in files if is_protected(p)]
    return _res(0 if bad else 1, True, {"protected": bad[:10]})


def _b_no_scratch(c):
    files = _patch_list(c)
    if files is None:
        return _na("no patch_files and no final_patch")
    bad = scratch_files(files)
    return _res(0 if bad else 1, True, {"scratch": bad[:10]})


def _b_nonempty(c):
    files = _patch_list(c)
    if files is None:
        return _na("no patch_files and no final_patch")
    ok, src = _nonempty(files)
    return _res(1 if ok else 0, True, {"source_files": src[:10], "files": len(files)})


# ---------------------------------------------------------------------------------------------------------------------
# X metrics
# ---------------------------------------------------------------------------------------------------------------------
def _xb_invented(c):
    x = _x(c)
    return _res(x["parsed_invented"] + x["unparsed_invented"], True,
                {"parsed": x["parsed_invented"], "unparsed": x["unparsed_invented"],
                 "examples": x["examples"].get("parsed_invented", []) + x["examples"].get("unparsed_invented", [])})


def _xb_bare_helper(c):
    x = _x(c)
    return _res(x["helper_parsed"] + x["helper_unparsed"] + x["helper_shell"], True,
                {"parsed": x["helper_parsed"], "unparsed": x["helper_unparsed"], "helper_shell": x["helper_shell"],
                 "examples": x["examples"].get("helper_shell", [])})


def _xb_key(key):
    def body(c):
        x = _x(c)
        return _res(x[key], True, {"examples": x["examples"].get(key, [])} if x[key] else None)
    return body


def _xb_exceed(c):
    calls = [r for r in _live_calls(c) if (_int(r.get("prompt_tokens")) or 0) >= COMPACTION_LINE]
    return _res(len(calls), True, {"max_prompt_tokens": max([_int(r.get("prompt_tokens")) or 0
                                                             for r in _live_calls(c)] or [0])})


def _xb_compactions(c):
    return _res(_compactions(c), True, None)


def _xb_runaway(c):
    caps = _d(_d(c["g"].get("run")).get("max_output_tokens"))
    n, ex = 0, []
    for r in _live_calls(c):
        cap = _num(caps.get(r.get("agent")))
        ct = _num(r.get("completion_tokens"))
        if r.get("finish_reason") == "length" or (cap and ct is not None and ct >= RUNAWAY_FRAC * cap):
            n += 1
            if len(ex) < 5:
                ex.append({"i": r.get("i"), "agent": r.get("agent"), "completion_tokens": ct,
                           "finish_reason": r.get("finish_reason")})
    return _res(n, True, {"examples": ex} if n else None)


def _xb_crash(c):
    cc = c["g"].get("crash_class")
    crashed = cc is not None or c["status"] == "model_error"
    return _res(1 if crashed else 0, True, {"crash_class": cc} if crashed else None)


def _xb_restarts(c):
    live = set(c["live"])
    return _res(sum(1 for r in c["calls"] if r.get("served") == "done_after_end" and r.get("agent") in live), True, None)


def _xb_capped(c):
    n = sum(1 for r in c["calls"] if r.get("served") == "cap")
    return _res(1 if n else 0, True, {"cap_records": n} if n else None)


X_IN_CLEAN = ("x_invented_tool_calls", "x_bare_helper_calls", "x_malformed_calls", "x_forbidden_edit_tools",
              "x_edit_helper_failures", "x_text_tool_calls", "x_compaction_exceedances", "x_compactions",
              "x_runaway_outputs", "x_cant_open_file", "x_crash", "x_live_restarts")


def _xb_clean(c):
    dirty = []
    for n in X_IN_CLEAN:
        r = globals()["m_" + n](c["inst"], c)
        if r["score"] != 0:
            dirty.append(n)
    return _res(0 if dirty else 1, True, {"dirty": dirty} if dirty else None)


def m_x_invented_tool_calls(instance, _c=None):
    return _metric("x_invented_tool_calls", instance, _c, _xb_invented)


def m_x_bare_helper_calls(instance, _c=None):
    return _metric("x_bare_helper_calls", instance, _c, _xb_bare_helper)


def m_x_malformed_calls(instance, _c=None):
    return _metric("x_malformed_calls", instance, _c, _xb_key("malformed"))


def m_x_forbidden_edit_tools(instance, _c=None):
    return _metric("x_forbidden_edit_tools", instance, _c, _xb_key("forbidden_edit"))


def m_x_edit_helper_failures(instance, _c=None):
    return _metric("x_edit_helper_failures", instance, _c, _xb_key("edit_fail"))


def m_x_text_tool_calls(instance, _c=None):
    return _metric("x_text_tool_calls", instance, _c, _xb_key("text_calls"))


def m_x_compaction_exceedances(instance, _c=None):
    return _metric("x_compaction_exceedances", instance, _c, _xb_exceed)


def m_x_compactions(instance, _c=None):
    return _metric("x_compactions", instance, _c, _xb_compactions)


def m_x_runaway_outputs(instance, _c=None):
    return _metric("x_runaway_outputs", instance, _c, _xb_runaway)


def m_x_cant_open_file(instance, _c=None):
    return _metric("x_cant_open_file", instance, _c, _xb_key("cant_open"))


def m_x_crash(instance, _c=None):
    return _metric("x_crash", instance, _c, _xb_crash)


def m_x_live_restarts(instance, _c=None):
    return _metric("x_live_restarts", instance, _c, _xb_restarts)


def m_x_capped(instance, _c=None):
    return _metric("x_capped", instance, _c, _xb_capped)


def m_x_clean(instance, _c=None):
    return _metric("x_clean", instance, _c, _xb_clean)


# ---------------------------------------------------------------------------------------------------------------------
# L metrics (live agent: locator; plan = its final reply)
# ---------------------------------------------------------------------------------------------------------------------
def _lb_all_files(c):
    gold = _gold_files(c)
    if not gold:
        return _na("no gold_files")
    plan = _reply(c)
    missing = [f for f in gold if not _path_named(plan, f)]
    return _res(0 if missing else 1, True, {"missing": missing[:10], "gold": len(gold)})


def _lb_files_frac(c):
    gold = _gold_files(c)
    if not gold:
        return _na("no gold_files")
    plan = _reply(c)
    hits = [f for f in gold if _path_named(plan, f)]
    return _res(float(len(hits)) / len(gold), True, {"named": len(hits), "gold": len(gold)})


def _lb_functions(c):
    names = []
    for f in _l(c["g"].get("gold_functions")):
        nm = _d(f).get("name")
        if isinstance(nm, str) and nm.strip() and nm.strip().lower() not in VACUOUS_FUNCTIONS:
            names.append(nm.strip())
    if not names:
        return _na("no gold functions (module level or none)")
    plan = _reply(c)
    hits = [n for n in names if re.search(r"(?<!\w)" + re.escape(n) + r"(?!\w)", plan)]
    return _res(float(len(hits)) / len(names), True, {"named": len(hits), "functions": len(names),
                                                      "missing": [n for n in names if n not in hits][:10]})


def _lb_format(c):
    t = _reply(c).lstrip()
    starts = t.startswith("FILES:")
    missing = [k for k in ("CAUSE", "FIX", "REPRO", "TESTS") if not re.search(r"(?m)^[ \t]*%s\b" % k, t)]
    return _res(1 if starts and not missing else 0, True, {"starts_files": starts, "missing": missing})


def _lb_words(c):
    t = _reply(c)
    if not t.strip():
        return _na("no reply")
    return _res(len(t.split()), True, None)


def _lb_within_words(c):
    t = _reply(c)
    if not t.strip():
        return _na("no reply")
    w = len(t.split())
    return _res(1 if w <= PLAN_WORDS_MAX else 0, True, {"words": w, "limit": PLAN_WORDS_MAX})


def _repro_uses(c):
    return [u for u in _uses(_stage(c)) if u["name"] == "run_command" and VERIFY_CMD.search(u["cmd"])
            and "--repro-only" in u["cmd"]]


def _lb_repro_fails(c):
    uses = _repro_uses(c)
    if not uses:
        return _res(0, True, {"repro_runs": 0})
    m = REPRO_HIT.search(_stdout(uses[-1]["resp"]) if uses[-1]["answered"] else "")
    return _res(1 if m else 0, True, {"repro_runs": len(uses), "answered": uses[-1]["answered"]})


def _lb_repro_valid(c):
    ec = c["ec"]
    if ec is None:
        return _na("no exec_checks")
    if "repro_text" in ec and not ec.get("repro_text"):
        return _res(0, True, "the locator wrote no reproduction")
    fo, pg = _ec(c, "repro_fails_orig"), _ec(c, "repro_passes_gold")
    if fo is None or pg is None:
        return _na("repro checks not computed")
    return _res(1 if fo and pg else 0, True, {"fails_orig": fo, "passes_gold": pg})


def _b_within_calls(c):
    n = sum(len(e["calls"]) for e in _stage(c))
    return _res(1 if n <= L_CALLS_MAX else 0, True, {"calls": n, "limit": L_CALLS_MAX})


def m_l_all_gold_files_named(instance, _c=None):
    return _metric("l_all_gold_files_named", instance, _c, _lb_all_files)


