# ---------------------------------------------------------------------------------------------------------------------
# F metrics (live agent: fixer; gradable cases only)
# ---------------------------------------------------------------------------------------------------------------------
def _fb_touch(frac):
    def body(c):
        gold = _gold_files(c)
        if not gold:
            return _na("no gold_files")
        files = _patch_list(c)
        if files is None:
            return _na("no patch_files and no final_patch")
        touched = set(p for p, _ in files)
        hit = [g for g in gold if g in touched]
        if frac:
            return _res(float(len(hit)) / len(gold), True, {"touched": len(hit), "gold": len(gold)})
        return _res(1 if len(hit) == len(gold) else 0, True, {"missing": [g for g in gold if g not in touched][:10]})
    return body


def _fb_notes(c):
    t = _reply(c)
    ch = re.search(r"(?m)^[ \t]*CHANGED:", t) is not None
    vf = re.search(r"(?m)^[ \t]*VERIFY:", t) is not None
    w = len(t.split())
    return _res(1 if ch and vf and w <= NOTES_WORDS_MAX else 0, True, {"changed": ch, "verify": vf, "words": w})


def _first_ok_edit(c):
    for u in _uses(_stage(c)):
        if u["name"] == "run_command" and EDIT_CMD.search(u["cmd"]) and u["answered"] \
                and re.match(r"\s*OK\b", _stdout(u["resp"])):
            return u
    return None


def _fb_first_edit_t(c):
    u = _first_ok_edit(c)
    if u is None:
        return _na("no edit.py result starting OK")
    ts = FOOT_T.findall(_flat(u["resp"]))
    return _res(int(ts[-1]), True, None) if ts else _na("the first OK edit has no helper footer")


def _fb_first_edit_in_time(c):
    u = _first_ok_edit(c)
    if u is None:
        return _na("no edit.py result starting OK")
    ts = FOOT_T.findall(_flat(u["resp"]))
    if not ts:
        return _na("the first OK edit has no helper footer")
    t = int(ts[-1])
    return _res(1 if t <= F_FIRST_EDIT_T else 0, True, {"t": t, "limit": F_FIRST_EDIT_T})


def _fb_verify_rounds(c):
    n = sum(1 for u in _uses(_stage(c)) if u["name"] == "run_command" and VERIFY_CMD.search(u["cmd"])
            and "--repro-only" not in u["cmd"])
    return _res(n, True, None)


