# ---------------------------------------------------------------------------------------------------------------------
# V metrics (live agent: verifier; gradable cases only)
# ---------------------------------------------------------------------------------------------------------------------
def _vb_goal(c):
    variant = c["g"].get("variant")
    if variant in ("gold", "wrong"):
        r = _b_hidden_pass(c)
        return r
    if variant == "empty":
        if c["status"] == "model_error":
            return _res(0, True, "model_error counts as a failure")
        return _b_nonempty(c)
    return _na("variant %r" % (variant,))


def _nodes(c):
    ec = c["ec"] or {}
    hn = _int(ec.get("hidden_nodes_pass"))
    pre = _int(ec.get("pre_hidden_nodes_pass"))
    if pre is None:
        pre = _int(c["g"].get("pre_hidden_nodes_pass"))
    return hn, pre


def _vb_not_worse(c):
    if c["ec"] is None:
        return _na("no exec_checks")
    hn, pre = _nodes(c)
    ap, co = _ec(c, "applies"), _ec(c, "compiles")
    if hn is None or pre is None or ap is None or co is None:
        return _na("hidden_nodes_pass, pre_hidden_nodes_pass, applies or compiles not computed")
    return _res(1 if hn >= pre and ap and co else 0, True, {"nodes": hn, "pre": pre, "applies": ap, "compiles": co})


def _vb_delta(c):
    hn, pre = _nodes(c)
    if hn is None or pre is None:
        return _na("hidden_nodes_pass or pre_hidden_nodes_pass not computed")
    return _res(hn - pre, True, {"nodes": hn, "pre": pre})


def _vb_submitted(c):
    n = sum(1 for u in _uses(_stage(c)) if u["name"] == "submit_patch")
    return _res(1 if n else 0, True, {"submits": n})


def _vb_finalize_first(c):
    uses = _uses(_stage(c))
    k = next((i for i, u in enumerate(uses) if u["name"] == "submit_patch"), None)
    if k is None:
        return _na("the verifier never called submit_patch")
    ok = any(u["name"] == "run_command" and FINALIZE_CMD.search(u["cmd"]) for u in uses[:k])
    return _res(1 if ok else 0, True, {"calls_before_submit": k})


